import {nextPage,previousPage} from './state.js';
import {h} from 'preact';
import {useLayoutEffect,useRef,useState} from 'preact/hooks';
import {Button,Notice,Loading} from '../../components/ui.jsx';
import {createPlanningScope} from '../work/planning-actions.js';
import {useScopedLoad} from '../insight/scoped-load.js';
export function useAction(after,scope=globalThis.location?.href??'people') {
  const owner=useRef(null),callback=useRef(after);callback.current=after;
  if(!owner.current||owner.current.scope!==scope){owner.current?.lifetime.dispose();owner.current={scope,lifetime:createPlanningScope()};}
  const resource=owner.current;
  const [state,setState]=useState({resource,busy:false,error:null,message:''});
  useLayoutEffect(()=>()=>resource.lifetime.dispose(),[resource]);
  const current=operation=>owner.current===resource&&operation.current();
  async function run(fn,success='Saved.',complete) {
    const operation=resource.lifetime.begin();
    if(!operation)return null;
    setState({resource,busy:true,error:null,message:''});
    try {
      const result=await fn(operation.signal);
      if(!current(operation))return null;
      complete?.(result);
      if(!current(operation))return null;
      callback.current?.(result);
      if(current(operation))setState({resource,busy:false,error:null,message:success});
      return result;
    }catch(error){if(current(operation))setState({resource,busy:false,error,message:''});return null;}
    finally{operation.finish();}
  }
  return {...(state.resource===resource?state:{busy:false,error:null,message:''}),run,
    clear:()=>setState({resource,busy:false,error:null,message:''})};
}
export function ActionNotice({action}) {return <><Notice error={action.error}/>{action.error?.details&&<ul role="alert">{Object.entries(action.error.details).filter(([,value])=>typeof value==='string').map(([key,value])=><li>{key}: {value}</li>)}</ul>}<Notice>{action.message}</Notice></>;}
export function PageButtons({page}) {
  return <nav aria-label="List pages" className="subnav">
    <Button type="button" disabled={!page.hasBack||page.loading} onClick={page.back}>Previous page</Button>
    <span>Page {page.number}</span>
    <Button type="button" disabled={!page.nextCursor||page.loading} onClick={page.next}>Next page</Button>
  </nav>;
}
export function usePaged(api,path,limit=25) {
  const [saved,setSaved]=useState({path,history:[null]});
  const history=saved.path===path?saved.history:[null],cursor=history.at(-1);
  const identity=JSON.stringify([path,limit,cursor]);
  const result=useScopedLoad(identity,()=>api.get(path+(path.includes('?')?'&':'?')+'limit='+limit+(cursor?'&cursor='+encodeURIComponent(cursor):'')),[identity]);
  return {...result,items:result.loading?[]:result.data?.items??[],nextCursor:result.loading?null:result.data?.nextCursor,number:history.length,
    hasBack:history.length>1,next:()=>!result.loading&&result.data?.nextCursor&&setSaved({path,history:nextPage(history,result.data.nextCursor)}),
    back:()=>setSaved({path,history:previousPage(history)}),reset:()=>setSaved({path,history:[null]})};
}
export function ListState({page,children}) {
  return <><Notice error={page.error}/>{page.loading?<Loading/>:page.error?<p>Refresh after checking your current access. No previous list is shown.</p>:<>{children}<PageButtons page={page}/></>}</>;
}
